import functools as _functools
import warnings as _warnings


def _httpx_shim_proxies(cls, transport_factory):
    _orig_init = cls.__init__

    @_functools.wraps(_orig_init)
    def __init__(self, *args, **kwargs):
        if "proxies" in kwargs:
            proxies = kwargs.pop("proxies")
            _warnings.warn(
                "The 'proxies' argument is deprecated; use 'proxy' or 'mounts' instead.",
                DeprecationWarning,
                stacklevel=2,
            )
            if proxies is not None:
                if isinstance(proxies, (str, URL, Proxy)):
                    kwargs.setdefault("proxy", proxies)
                else:
                    mounts = dict(kwargs.get("mounts") or {})
                    for pattern, p in dict(proxies).items():
                        mounts.setdefault(
                            pattern, None if p is None else transport_factory(proxy=p)
                        )
                    kwargs["mounts"] = mounts
        if "app" in kwargs:
            app = kwargs.pop("app")
            _warnings.warn(
                "The 'app' argument is deprecated; use 'transport=WSGITransport(app=...)' "
                "or 'transport=ASGITransport(app=...)' instead.",
                DeprecationWarning,
                stacklevel=2,
            )
            if app is not None and kwargs.get("transport") is None:
                kwargs["transport"] = (
                    WSGITransport(app=app) if cls is Client else ASGITransport(app=app)
                )
        _orig_init(self, *args, **kwargs)

    cls.__init__ = __init__


_httpx_shim_proxies(Client, HTTPTransport)
_httpx_shim_proxies(AsyncClient, AsyncHTTPTransport)
